  ["Roomscale movement"] = "Oda ölçeğinde hareket",
  ["Move the player capsule with physical horizontal head movement.\nUses native collision/steps and preserves stick or WASD movement.\nSuspended in menus, vehicles and scripted movement."] = "Oyuncu kapsülünü başın fiziksel yatay hareketiyle taşır.\nYerel çarpışma/basamakları kullanır ve çubuk veya WASD hareketini korur.\nMenülerde, araçlarda ve senaryolu harekette askıya alınır.",
  ["Stick / snap only"] = "Yalnızca çubuk / adımlı dönüş",
  ["Head + free-look cone"] = "Baş + serbest bakış konisi",
  ["HMD + controllers"] = "HMD + kontrolcüler",
  ["Hybrid (default)"] = "Hibrit (varsayılan)",
  ["Body rotation"] = "Gövde dönüşü",
  ["Hybrid: use the head cone while upright.\nLooking down by 10 degrees or bending by 5 degrees uses HMD + controllers.\nReturn below 8 / 3 degrees; the current body heading is preserved at handover.\nHMD + controllers always disables the body cones. Missing tracking holds heading."] = "Hibrit: dik dururken baş konisini kullanır.\n10° aşağı bakmak veya 5° eğilmek HMD + kontrolcülere geçer.\n8 / 3°'nin altında geri döner; geçişte mevcut gövde yönü korunur.\nHMD + kontrolcüler gövde konilerini her zaman kapatır. Takip yoksa yön korunur.",
  ["Never (VRIK always on)"] = "Asla (VRIK her zaman açık)",
  ["Staged scenes and up (Tier 2+)"] = "Sahnelenmiş sahneler ve üstü (Tier 2+)",
  ["Tier 3 and up"] = "Tier 3 ve üstü",
  ["Cinematics (Tier 4+)  [default]"] = "Ara sahneler (Tier 4+)  [varsayılan]",
  ["Full cinematics only (Tier 5)"] = "Yalnızca tam ara sahneler (Tier 5)",
  ["Suspend VRIK in cutscenes (on foot)"] = "Ara sahnelerde VRIK'i askıya al (yaya)",
  ["Applies only on foot. VRIK yields to the scene animation at or above this tier.\nThe vehicle threshold is configured separately below."] = "Yalnızca yayayken geçerlidir. VRIK bu seviyede ve üstünde sahne animasyonuna devreder.\nAraç eşiği aşağıda ayrıca ayarlanır.",
  ["Suspend VRIK in cutscenes (vehicle)"] = "Ara sahnelerde VRIK'i askıya al (araç)",
  ["Applies in vehicles, including passenger window combat.\nVRIK yields to the scene animation at or above this tier. Never keeps VRIK enabled."] = "Yolcu penceresinden çatışma dahil, araçlarda geçerlidir.\nVRIK bu seviyede ve üstünde sahne animasyonuna devreder. 'Asla' VRIK'i açık tutar.",
  ["Free-look cone"] = "Serbest bakış konisi",
  ["%.0f deg"] = "%.0f°",
  ["How far your head may turn before the body starts coming around.\nThe body settles toward the centre, then restores the full free-look zone.\nDefault: 10 degrees. Hybrid uses this value while looking ahead."] = "Gövde dönmeye başlamadan önce başının ne kadar dönebileceği.\nGövde merkeze doğru yerleşir, ardından tam serbest bakış bölgesini geri yükler.\nVarsayılan: 10°. Hibrit mod ileri bakarken bu değeri kullanır.",
  ["Free-look cone when looking down"] = "Aşağı bakarken serbest bakış konisi",
  ["Extra room to reach chest-mounted items.\nBlends in from 10 to 30 degrees of downward head tilt.\nNever narrows the normal cone; set the same value to disable widening."] = "Göğse takılı eşyalara uzanmak için ek alan.\nBaşın 10 ile 30° arasında aşağı eğilmesiyle kademeli devreye girer.\nNormal koniyi asla daraltmaz; genişletmeyi kapatmak için aynı değeri gir.",
  ["Free-look cone in water"] = "Suda serbest bakış konisi",
  ["One fixed cone on the surface and underwater.\nLooking down and physical bending do not widen it. Default: 5 degrees."] = "Yüzeyde ve su altında tek bir sabit koni.\nAşağı bakmak ve fiziksel eğilme onu genişletmez. Varsayılan: 5°.",
  ["Body free-look cones are disabled in HMD + controllers mode."] = "HMD + kontrolcüler modunda gövde serbest bakış konileri kapalıdır.",
  ["Hybrid: head cone upright; HMD + controllers when looking down or bending."] = "Hibrit: dikken baş konisi; aşağı bakarken veya eğilirken HMD + kontrolcüler.",
  ["Body movement free zone"] = "Gövde hareketi serbest bölgesi",
