  ["AUTO-CALIBRATING: stretch arms STRAIGHT OUT to the sides,"] = "OTOMATİK KALİBRASYON: kollarını yanlara DÜMDÜZ aç,",
  ["stand straight facing forward. Hold for %.1fs (%.0f%%)."] = "dik dur ve ileri bak. %.1f sn tut (%%%.0f).",
  ["Start Auto-Calibration (T-pose, 4s)"] = "Otomatik kalibrasyonu başlat (T-poz, 4 sn)",
  ["Press once, then stretch BOTH gizmo hands OUT to the sides at shoulder height\nand stand straight facing forward. The mod measures the visible controller\npositions, computes shoulder pivots + arm scale, and saves the result\nto vrik_calibration.ini."] = "Bir kez bas, ardından İKİ gizmo elini omuz hizasında yanlara AÇ\nve ileri bakarak dik dur. Mod görünen kontrolcü\nkonumlarını ölçer, omuz pivotlarını + kol ölçeğini hesaplar ve sonucu\nvrik_calibration.ini dosyasına kaydeder.",
  ["Saved."] = "Kaydedildi.",
  ["Camera: neck + 15 cm forward, eyes + 10 cm up"] = "Kamera: boyun + 15 cm ileri, gözler + 10 cm yukarı",
  ["Reset camera to neck"] = "Kamerayı boyuna sıfırla",
  ["Uses the neutral neck, 15 cm forward and 10 cm above reference eyes.\nResets camera trims; no stance, head direction or Bake measurement is needed."] = "Nötr boynu, referans gözlerin 15 cm önünde ve 10 cm üstünde kullanır.\nKamera ince ayarlarını sıfırlar; duruş, baş yönü veya Bake ölçümü gerekmez.",
