  ["Stereo module not installed."] = "Stereo modülü yüklü değil.",
  ["The engine hooks did not load, so everything below is inert and the headset is on the plain mono path. Either CyberpunkVR_StereoModuleEnable is 0, or bin\\x64\\vrport_nostereo.txt exists. See the \"Stereo:\" line in cyberpunkvrport.log."] = "Motor kancaları yüklenmedi; bu yüzden aşağıdaki her şey etkisizdir ve kulaklık düz mono yolda çalışır. Ya CyberpunkVR_StereoModuleEnable 0'dır ya da bin\\x64\\vrport_nostereo.txt mevcuttur. cyberpunkvrport.log içindeki \"Stereo:\" satırına bak.",
  ["LEFT"] = "SOL",
  ["RIGHT"] = "SAĞ",
  ["Stereo active  (%s = VRCAM, %s = MAIN)"] = "Stereo etkin  (%s = VRCAM, %s = MAIN)",
  ["No second eye right now -> both eyes get MAIN (mono)"] = "Şu anda ikinci göz yok -> iki göz de MAIN alır (mono)",
  ["Expected in menus and while loading. If it stays here in gameplay: the VRCAM component is off, or vrcam.json names a camera the player entity does not carry."] = "Menülerde ve yükleme sırasında normaldir. Oynanışta da böyle kalırsa: VRCAM bileşeni kapalıdır veya vrcam.json oyuncu varlığında olmayan bir kamerayı adlandırır.",
  ["Stereo submit off -> both eyes get MAIN (mono)"] = "Stereo gönderimi kapalı -> iki göz de MAIN alır (mono)",
  ["vrcam eye age %u ms  (stale over %u)   eye submits %llu"] = "vrcam göz yaşı %u ms  (%u üstü bayat)   göz gönderimleri %llu",
  ["vrcam eye: never produced a frame"] = "vrcam gözü: hiç kare üretmedi",
  ["Send VRCAM to the %s EYE"] = "VRCAM'i %s GÖZE gönder",
  ["Off = the old behaviour, MAIN duplicated into both eyes.\nOn = the %s eye gets the VRCAM view's own final colour --\nthe same image the desktop mirror shows -- re-encoded to the\nswapchain's sRGB format and scaled to the eye size."] = "Kapalı = eski davranış, MAIN iki göze de kopyalanır.\nAçık = %s göz VRCAM görünümünün kendi son rengini alır --\nmasaüstü aynasının gösterdiği görüntünün aynısı --, swapchain'in\nsRGB biçimine yeniden kodlanır ve göz boyutuna ölçeklenir.",
  ["snapshot copies %llu   skips %llu   vrcam RTV hits %llu"] = "anlık görüntü kopyaları %llu   atlamalar %llu   vrcam RTV isabetleri %llu",
  ["Eye staleness limit (ms)"] = "Göz bayatlık sınırı (ms)",
  ["How long the last VRCAM frame stays usable. Past this the %s\neye falls back to MAIN -- one eye frozen while the other moves\nis far worse to look at than mono."] = "Son VRCAM karesinin ne kadar süre kullanılabileceği. Bundan sonra %s\ngöz MAIN'e döner -- diğeri hareket ederken donmuş bir göz,\nmonodan çok daha kötü görünür.",
  ["VRCAM DLSS: %s  (follows MAIN's upscaler, no switch)"] = "VRCAM DLSS: %s  (MAIN'in ölçekleyicisini izler, anahtar yok)",
  ["ON"] = "AÇIK",
  ["off"] = "kapalı",
  ["On whenever MAIN is upscaling with DLSS: vrcam gets its own\nStreamline viewport and renders below its target.\nOff for DLAA / TAA / no upscaler. Change it in the game's\ngraphics settings, not here."] = "MAIN DLSS ile ölçeklerken açıktır: vrcam kendi\nStreamline görünüm alanını alır ve hedefinin altında render eder.\nDLAA / TAA / ölçekleyici yokken kapalıdır. Oyunun grafik\nayarlarından değiştir, buradan değil.",
  ["Match VRCAM projection to MAIN  (fov / zoom / near / far)"] = "VRCAM projeksiyonunu MAIN'e eşle  (fov / zoom / near / far)",
  ["VRCAM component  (RTTI Toggle: force ON/OFF)"] = "VRCAM bileşeni  (RTTI anahtarı: AÇIK/KAPALI zorla)",
  ["component %s   camera %s"] = "bileşen %s   kamera %s",
  ["view nodes: main %llu   other %llu   vrcam %llu"] = "görünüm düğümleri: main %llu   diğer %llu   vrcam %llu",
  ["VRCAM Mirror  (separate window, for capture)"] = "VRCAM aynası  (ayrı pencere, kayıt için)",
  ["vrcam fov %.2f  (asset %.2f)   main yy %.5f  fov %.2f   ADS x%.3f"] = "vrcam fov %.2f  (varlık %.2f)   main yy %.5f  fov %.2f   ADS x%.3f",
  ["Diagnostics"] = "Tanılama",
  ["Compact ADS camera telemetry (in-headset)"] = "Kompakt ADS kamera telemetrisi (kulaklıkta)",
  ["A small panel that stays up after F10 is closed, reporting what the ENGINE did to the camera when the sights came up:\ndelta and peak in centimetres, right/forward/up in the heading's own basis, against a baseline captured while hip firing.\nStereo submission is unaffected."] = "F10 kapatıldıktan sonra da açık kalan küçük bir panel; nişangah kaldırıldığında MOTORUN kameraya ne yaptığını bildirir:\nsantimetre cinsinden fark ve tepe, yönün kendi tabanında sağ/ileri/yukarı, kalçadan ateş ederken yakalanan referansa göre.\nStereo gönderimi etkilenmez.",
  ["Telemetry X"] = "Telemetri X",
  ["Telemetry Y"] = "Telemetri Y",
  ["Normalised position in the eye image"] = "Göz görüntüsündeki normalize konum",
  ["Stereo logging -> cyberpunkvrport.log"] = "Stereo günlüğü -> cyberpunkvrport.log",
  ["Committed snapshot of the VRCAM final"] = "VRCAM son görüntüsünün sabitlenmiş anlık görüntüsü",
  ["Off = read the engine's transient directly. That target is a\nframe-graph allocation which a later pass aliases, which is what\nmade the image alternate bright/dark. Leave on."] = "Kapalı = motorun geçici hedefini doğrudan okur. Bu hedef,\nsonraki bir geçişin yeniden kullandığı bir frame graph tahsisidir;\ngörüntünün açık/koyu arasında gidip gelmesinin nedeni buydu. Açık bırak.",
  ["Snapshot at the tonemap node instead of RenderFinal2D"] = "RenderFinal2D yerine tonemap düğümünde anlık görüntü",
  ["Node CPU profiler  (per-node self+incl ms)"] = "Düğüm CPU profilleyicisi  (düğüm başına öz+toplam ms)",
  ["frame %.2f ms   dispatch: main %.2f (%u)  vrcam %.2f (%u)"] = "kare %.2f ms   dispatch: main %.2f (%u)  vrcam %.2f (%u)",
  ["Dump node audit -> log  (resets window)"] = "Düğüm denetimi -> günlük  (pencereyi sıfırlar)",
  ["top %d by self ms/frame   (main | vrcam)"] = "öz ms/kareye göre ilk %d   (main | vrcam)",
  ["Driving -- hands on the wheel"] = "Sürüş -- eller direksiyonda",
  ["Grab the wheel with the grips"] = "Direksiyonu kavrama tuşlarıyla tut",
  ["While DRIVING, bring a hand to where the driving animation holds the\nwheel (or the handlebars) and squeeze that grip: the arm is handed back\nto the game's own animation -- hand on the wheel, fingers wrapped around\nit -- instead of following the controller. Release the grip and it goes\nback to your hand.\n\nEach hand is independent: hold the wheel with one and keep the other on\na gun. While a hand is at the wheel that grip does nothing else (no\nholster equip, no magazine grab)."] = "SÜRERKEN elini sürüş animasyonunun direksiyonu (veya gidonu)\ntuttuğu yere götür ve o kavrama tuşunu sık: kol, kontrolcüyü izlemek\nyerine oyunun kendi animasyonuna devredilir -- el direksiyonda, parmaklar\netrafına sarılı. Kavrama tuşunu bırak, kol\neline geri döner.\n\nEller bağımsızdır: biriyle direksiyonu tut, diğerini\nsilahta tut. Bir el direksiyondayken o kavrama tuşu başka bir şey yapmaz (kılıftan\nsilah alma yok, şarjör kavrama yok).",
  ["Grab radius (m)"] = "Kavrama yarıçapı (m)",
  ["How close your hand has to be to the animated hand before the\ngrip counts as grabbing the wheel. Bigger = easier to catch a\nwheel you cannot see; too big and every grip in a car grabs."] = "Kavrama tuşunun direksiyonu tutma sayılması için elinin\nanimasyonlu ele ne kadar yakın olması gerektiği. Büyük = göremediğin\ndireksiyonu yakalamak daha kolay; çok büyükse araçtaki her kavrama tutar.",
  ["Car full lock at (deg)"] = "Tam kilit açısı (°)",
  ["Wheel sensitivity: hand rotation from the grab position to full lock.\nOne hand uses a hub calibrated where you grab; two use their connecting line.\nAdding or releasing a hand keeps the current turn.\n180 = a half turn to either full lock (default). Lower = more sensitive.\nThe car's cabin wheel has twice its native travel; road-wheel lock is unchanged.\nTravel beyond full lock keeps the same neutral position."] = "Direksiyon hassasiyeti: kavrama konumundan tam kilide kadar el dönüşü.\nTek el, kavradığın yerde kalibre edilen bir göbek kullanır; iki el aralarındaki çizgiyi.\nEl eklemek veya bırakmak mevcut dönüşü korur.\n180 = her iki yöne tam kilide yarım tur (varsayılan). Düşük = daha hassas.\nAraç içi direksiyonun yerel hareketi iki katıdır; tekerlek kilidi değişmez.\nTam kilidin ötesindeki hareket aynı nötr konumu korur.",
  ["Steering deadzone (deg)"] = "Direksiyon ölü bölgesi (°)",
  ["Tilt around centre that steers nothing at all.\nRaise it if the car drifts while you hold the wheel straight;\nevery degree here is a degree of dead wheel off centre.\nThe full range still ends at 'Full lock at', so widening the\ndeadzone does not make the steering jump."] = "Merkez etrafında hiç yönlendirmeyen eğim.\nDireksiyonu düz tutarken araç kayıyorsa artır;\nburadaki her derece, merkez dışında bir derece ölü direksiyondur.\nTam aralık yine de 'Tam kilit açısı' değerinde biter, bu yüzden\nölü bölgeyi genişletmek direksiyonda sıçrama yapmaz.",
  ["Steering prediction"] = "Direksiyon tahmini",
  ["Gently anticipate a continuing turn from recent hand movement.\nLimited to 8 ms and 0.5 degrees; neutral stays unchanged.\nPrediction stops on a pause, reversal or grip change.\nOff by default. It cannot anticipate the start of a turn."] = "Son el hareketinden devam eden bir dönüşü nazikçe öngörür.\n8 ms ve 0.5° ile sınırlıdır; nötr değişmez.\nTahmin duraklamada, yön değişiminde veya kavrama değişiminde durur.\nVarsayılan olarak kapalı. Bir dönüşün başlangıcını öngöremez.",
  ["Prediction horizon (ms)"] = "Tahmin ufku (ms)",
  ["Horn -- hand on the wheel hub"] = "Korna -- el direksiyon göbeğinde",
  ["While DRIVING, put a hand on the MIDDLE of the wheel -- where you would\nslap a real horn -- and the car honks for as long as it stays there.\nNo grip needed; a hand that is GRABBING the wheel never honks."] = "SÜRERKEN elini direksiyonun ORTASINA koy -- gerçek bir kornaya\nvuracağın yere -- ve el orada kaldığı sürece araç korna çalar.\nKavrama gerekmez; direksiyonu TUTAN el asla korna çalmaz.",
  ["Horn hub radius (m)"] = "Korna göbeği yarıçapı (m)",
  ["How near the wheel centre the hand counts as on the hub.\nBigger = easier to find the horn without seeing it; too big\nand it reaches the rim, so every grab honks."] = "Elin göbekte sayılması için direksiyon merkezine ne kadar yakın olması gerektiği.\nBüyük = kornayı görmeden bulmak daha kolay; çok büyükse\njanta ulaşır ve her kavrama korna çalar.",
  ["Trigger fires the gun while driving"] = "Sürerken tetik silahı ateşler",
  ["Draw a weapon in the driver seat and the RIGHT TRIGGER stops being the\nthrottle and becomes the gun: drive with the left hand on the wheel and\nshoot with the right.\n\nThe throttle LATCHES at whatever it was when the weapon came out, so the\ncar keeps rolling, and the LEFT STICK forward/back trims that speed while\nyou shoot. Holster the weapon and the trigger is the throttle again.\n\nWhile the weapon is out the left stick's forward/back is taken by the\ntrim: no lean / rock and no autodrive gesture until you holster."] = "Sürücü koltuğunda silah çek; SAĞ TETİK artık\ngaz değil, silah olur: sol elle direksiyonda sür ve\nsağla ateş et.\n\nGaz, silah çekildiği andaki değerde KİLİTLENİR; böylece\naraç yuvarlanmaya devam eder ve SOL ÇUBUK ileri/geri ateş ederken\nbu hızı ayarlar. Silahı kılıfa koy, tetik yeniden gaz olur.\n\nSilah çekiliyken sol çubuğun ileri/geri ekseni\nince ayara ayrılır: kılıfa koyana kadar eğilme / sallanma ve otomatik sürüş hareketi yok.",
  ["Throttle trim rate (/s)"] = "Gaz ayar hızı (/s)",
  ["How much of the throttle's full travel the left stick adds or\nremoves per second while a weapon is out.\n0.5 = two seconds held to go from idle to floored."] = "Silah çekiliyken sol çubuğun saniyede gazın tam hareketinin\nne kadarını ekleyip çıkardığı.\n0.5 = rölantiden tam gaza iki saniye basılı tutma.",
  ["driving %d   at wheel  L %d R %d   hold  L %.2f R %.2f"] = "sürüş %d   direksiyonda  L %d R %d   tutuş  L %.2f R %.2f",
  ["steer  %+.1f deg  ->  stick %+.2f     horn  L %d R %d"] = "direksiyon  %+.1f°  ->  çubuk %+.2f     korna  L %d R %d",
  ["SEATED CAMERA OFFSET"] = "OTURMA KAMERA OFSETİ",
  ["Head offsets in GENERAL are a standing calibration. Seated, the game's own\nvehicle camera is already where it should be -- which is why the port drops\nits two automatic bakes in a vehicle -- so a standing offset carries the view\noff the seat instead of correcting it.\n\nThese three are added to the Head sliders while you are in a vehicle and\nignored the moment you step out, so the car and the street can be tuned\nseparately. Zero = the car keeps exactly the offset it has today."] = "GENEL'deki baş ofsetleri ayakta kalibrasyondur. Otururken oyunun kendi\naraç kamerası zaten olması gereken yerdedir -- port bu yüzden araçta\niki otomatik ölçümünü bırakır --, dolayısıyla ayakta ofset görüşü\nkoltuktan uzaklaştırır, düzeltmez.\n\nBu üçü araçtayken Baş kaydırıcılarına eklenir ve\ndışarı adım attığın anda yok sayılır; böylece araç ve sokak ayrı\nayarlanabilir. Sıfır = araç bugünkü ofsetini aynen korur.",
  ["Car Head X right"] = "Araçta baş X sağ",
  ["Car Head Y forward"] = "Araçta baş Y ileri",
  ["Car Head Z up"] = "Araçta baş Z yukarı",
  ["   (window combat: use GENERAL > Head offsets)"] = "   (pencereden çatışma: GENEL > Baş ofsetlerini kullan)",
