  ["Balanced"] = "Dengeli",
  ["Performance"] = "Performans",
  ["The center follows game DLSS/DLAA. Peripheral DLAA uses 100%% / 75%% / 50%% of the game's render resolution."] = "Merkez oyunun DLSS/DLAA'sını izler. Çevresel DLAA, oyunun render çözünürlüğünün %%100 / %%75 / %%50'sini kullanır.",
