  ["Disable Mouse Y (Pitch)"] = "Fare Y'yi devre dışı bırak (yunuslama)",
  ["Suppress mouse/right-stick pitch so only the HMD controls\nvertical look. Applied by the CET VRIK mod and the\nXInput merge. On by default."] = "Dikey bakışı yalnızca HMD kontrol etsin diye fare/sağ çubuk\nyunuslamasını bastırır. CET VRIK modu ve\nXInput birleştirmesi tarafından uygulanır. Varsayılan olarak açık.",
