  ["Slow (best)"] = "Yavaş (en iyi)",
  ["Optical flow"] = "Optik akış",
  ["Off (game vectors only)"] = "Kapalı (yalnızca oyun vektörleri)",
  ["The game's motion vectors already describe almost all motion; optical flow adds GPU time\nand memory for what they miss (some particles and effects)."] = "Oyunun hareket vektörleri neredeyse tüm hareketi zaten tanımlar; optik akış, kaçırdıkları için\n(bazı parçacıklar ve efektler) GPU süresi ve bellek ekler.",
  ["NVIDIA's frame generation model on the game's motion vectors and depth. Highest quality, RTX 40/50."] = "NVIDIA'nın oyunun hareket vektörleri ve derinliği üzerinde çalışan kare üretim modeli. En yüksek kalite, RTX 40/50.",
  ["Adaptive real-frame pacing"] = "Uyarlanabilir gerçek kare temposu",
  ["Up to half headset refresh. Leaves more GPU time for generated frames when adjacent real frames are being missed."] = "Kulaklık yenileme hızının en fazla yarısı. Komşu gerçek kareler kaçırıldığında üretilen karelere daha fazla GPU süresi bırakır.",
  ["Uses game motion vectors and depth in both eyes. Adds one intermediate frame between real frames."] = "İki gözde oyunun hareket vektörlerini ve derinliğini kullanır. Gerçek kareler arasına bir ara kare ekler.",
  ["HUD"] = "HUD",
  ["Enable HUD panel"] = "HUD panelini etkinleştir",
  ["Head / free-look cone"] = "Baş / serbest bakış konisi",
  ["Follow"] = "Takip",
  ["Catch up beyond the cone, or after 3 seconds at rest when the yaw offset is over 10 degrees inside it."] = "Koninin ötesinde veya içindeki sapma farkı 10°'yi aştığında 3 saniyelik hareketsizlikten sonra yetişir.",
  ["HUD FOV"] = "HUD FOV",
  ["Stereo depth"] = "Stereo derinlik",
  ["Off: the HUD has the same direction in both eyes.\nOn: place it at the selected physical depth."] = "Kapalı: HUD iki gözde aynı yöndedir.\nAçık: seçilen fiziksel derinliğe yerleştirir.",
  ["Depth"] = "Derinlik",
  ["Brightness"] = "Parlaklık",
  ["Shadow / outline"] = "Gölge / dış hat",
  ["Glow"] = "Parıltı",
  ["INTERACTIONS / DIALOGS"] = "ETKİLEŞİMLER / DİYALOGLAR",
  ["World-space interactions / dialogs"] = "Dünya uzayında etkileşimler / diyaloglar",
  ["Interaction free-look cone"] = "Etkileşim serbest bakış konisi",
  ["Loot free-look cone"] = "Ganimet serbest bakış konisi",
  ["Used while the loot panel and item description are visible. Default: 10 degrees."] = "Ganimet paneli ve eşya açıklaması görünürken kullanılır. Varsayılan: 10°.",
  ["Interaction distance"] = "Etkileşim mesafesi",
  ["Interaction FOV"] = "Etkileşim FOV",
  ["Interaction prompts and dialog choices share this panel. It follows only beyond the cone; no delayed catch-up at rest."] = "Etkileşim istemleri ve diyalog seçenekleri bu paneli paylaşır. Yalnızca koninin ötesinde takip eder; hareketsizken gecikmeli yetişme yok.",
  ["Element"] = "Öğe",
  ["Not currently visible in gameplay; settings are still saved."] = "Şu anda oynanışta görünmüyor; ayarlar yine de kaydedilir.",
  ["Show element"] = "Öğeyi göster",
  ["Horizontal offset"] = "Yatay ofset",
  ["Vertical offset"] = "Dikey ofset",
  ["Size"] = "Boyut",
  ["Opacity"] = "Opaklık",
  ["Reset element"] = "Öğeyi sıfırla",
  ["Reset all elements"] = "Tüm öğeleri sıfırla",
  ["CONTROLS"] = "KONTROLLER",
  ["DRIVING"] = "SÜRÜŞ",
  ["BINDINGS"] = "ATAMALAR",
  ["Movement, weapon aiming and physical interaction shortcuts."] = "Hareket, silah nişanı ve fiziksel etkileşim kısayolları.",
  ["Hand aim  (off = Decoupled VR Head Aim)"] = "El ile nişan  (kapalı = ayrık VR baş nişanı)",
  ["ON (Hand Aim): the controller points the weapon and VRIK drives the arms.\nOFF (Decoupled VR Head Aim): the WEAPON follows your head instead, the game\nkeeps owning its position and its ADS animations, and VRIK stands down for\nthe weapon arm. Either way the shot leaves the real muzzle, for guns and\nprojectiles alike, and free-look while aiming is preserved."] = "AÇIK (el ile nişan): silahı kontrolcü yönlendirir, kolları VRIK hareket ettirir.\nKAPALI (ayrık VR baş nişanı): SİLAH bunun yerine başını izler, oyun\nkonumunu ve ADS animasyonlarını yönetmeye devam eder ve VRIK silah kolunu\nbırakır. Her iki durumda da atış gerçek namludan çıkar, mermiler\nve fırlatılan mühimmat için de; nişan alırken serbest bakış korunur.",
  ["Weapon Aim laser dot (where the bullet hits)"] = "Nişan lazer noktası (merminin isabet ettiği yer)",
  ["Red dot projected from the actual weapon muzzle direction through the\ngame camera -- marks exactly where the bullet will fly."] = "Silah namlusunun gerçek yönünden oyun kamerası üzerinden\nyansıtılan kırmızı nokta -- merminin tam olarak nereye uçacağını gösterir.",
  ["Controller vibration"] = "Kontrolcü titreşimi",
  ["Haptics: every round by weapon class (handgun, rifle, shotgun, sniper),\nmelee block and parry, bullet block and deflect, reaching a belt element,\npulling a grenade pin. Two-handed grip: both hands; one hand: one."] = "Dokunsal geri bildirim: silah sınıfına göre her atış (tabanca, tüfek, pompalı, keskin nişancı),\nyakın dövüşte blok ve savuşturma, mermi bloklama ve saptırma, kemer öğesine uzanma,\nel bombası pimini çekme. İki elle tutuş: iki el; tek el: bir.",
  ["Vibration strength"] = "Titreşim gücü",
  ["Enable VR -> XInput merge"] = "VR -> XInput birleştirmesini etkinleştir",
  ["OR the VR controller state into XInput gamepad 0 every poll.\nOff = the game only sees a physical pad / nothing."] = "Her yoklamada VR kontrolcü durumunu XInput oyun kumandası 0'a VEYA ile birleştirir.\nKapalı = oyun yalnızca fiziksel kumandayı / hiçbir şeyi görür.",
  ["Weapon holsters (reach + right grip)"] = "Silah kılıfları (uzanma + sağ kavrama)",
  ["Immersive holsters"] = "Sürükleyici kılıflar",
  ["ON  - equip is chosen by the VISUAL holster you reach for:\n      over the right shoulder = primary weapon (rifle / sniper),\n      hip with a katana = melee, hip with a pistol = sidearm.\nOFF - ignore visual holsters, fixed slot per zone:\n      over-shoulder = EquipmentSlot1, right hip = Slot2, left hip = Slot3.\nReach to the zone and squeeze the RIGHT grip to equip / unequip."] = "AÇIK  - silah, uzandığın GÖRSEL kılıfa göre seçilir:\n      sağ omzun üstü = birincil silah (tüfek / keskin nişancı),\n      katanalı kalça = yakın dövüş, tabancalı kalça = yan silah.\nKAPALI - görsel kılıflar yok sayılır, bölge başına sabit yuva:\n      omuz üstü = EquipmentSlot1, sağ kalça = Slot2, sol kalça = Slot3.\nBölgeye uzan ve kuşanmak / bırakmak için SAĞ kavrama tuşunu sık.",
  ["Locomotion direction"] = "Hareket yönü",
  ["Analog movement"] = "Analog hareket",
  ["On: speed follows left-stick travel. Off: the current fixed-speed movement (default).\nVehicle controls keep their existing response."] = "Açık: hız sol çubuğun hareketini izler. Kapalı: mevcut sabit hızlı hareket (varsayılan).\nAraç kontrolleri mevcut tepkilerini korur.",
  ["Left stick deadzone"] = "Sol çubuk ölü bölgesi",
  ["Right stick deadzone"] = "Sağ çubuk ölü bölgesi",
  ["Full input threshold"] = "Tam giriş eşiği",
  ["Raw travel that produces full analog input and activates sprint, dash and crouch.\nThe usable travel between the deadzone and this threshold maps to 0-100%%."] = "Tam analog giriş üreten ve koşma, atılma ve çömelmeyi etkinleştiren ham hareket.\nÖlü bölge ile bu eşik arasındaki kullanılabilir hareket %%0-100'e karşılık gelir.",
  ["Game (camera)"] = "Oyun (kamera)",
  ["HMD (head)"] = "HMD (baş)",
  ["Left hand"] = "Sol el",
  ["Right hand"] = "Sağ el",
  ["Move source"] = "Hareket kaynağı",
  ["Game     - left stick walks the way the camera faces (vanilla).\nHMD      - left stick walks the way the headset faces.\nLeft/Right hand - walks the way the chosen controller points.\nVehicles always keep game heading."] = "Oyun     - sol çubuk kameranın baktığı yöne yürütür (orijinal).\nHMD      - sol çubuk kulaklığın baktığı yöne yürütür.\nSol/Sağ el - seçilen kontrolcünün gösterdiği yöne yürütür.\nAraçlar her zaman oyun yönünü korur.",
  ["Breaststroke swimming"] = "Kurbağalama yüzme",
  ["Physical crouch"] = "Fiziksel çömelme",
  ["Physical crouch depth"] = "Fiziksel çömelme derinliği",
  ["%.0f cm"] = "%.0f cm",
  ["Height loss after the measured lean. Standing back up releases physical crouch."] = "Ölçülen eğilmeden sonraki yükseklik kaybı. Yeniden dik durmak fiziksel çömelmeyi bırakır.",
  ["In water: reach forward with both hands, sweep out and pull back.\nMovement begins during the pull. Gentle strokes swim normally; fast pulls boost.\nSwim where the headset points, including up/down; no stick needed.\nTo rise, raise separated hands to chest level and push both down.\nRepeat strokes to keep moving. Pull the left stick back to stop."] = "Suda: iki elinle ileri uzan, dışa doğru süpür ve geri çek.\nHareket çekiş sırasında başlar. Yavaş kulaçlar normal yüzer; hızlı çekişler hızlandırır.\nKulaklığın gösterdiği yöne yüzersin, yukarı/aşağı dahil; çubuk gerekmez.\nYükselmek için ayrık ellerini göğüs hizasına kaldır ve ikisini de aşağı it.\nİlerlemeye devam etmek için kulaçları tekrarla. Durmak için sol çubuğu geri çek.",
  ["Ladder grip climbing"] = "Merdivene kavrayarak tırmanma",
  ["Grip a side rail or rung. Pull the hand down to climb up,\nor move it up to climb down. Release to stop. Native pelvis and legs stay on the ladder."] = "Yan korkuluğu veya basamağı kavra. Yukarı tırmanmak için eli aşağı çek,\naşağı inmek için yukarı hareket ettir. Durmak için bırak. Yerel pelvis ve bacaklar merdivende kalır.",
  ["Auto finish near ladder top"] = "Merdiven tepesinde otomatik bitir",
  ["After an upward pull near the top, finish climbing even when grips are released.\nMove the stick or push a held hand upward to cancel."] = "Tepeye yakın yukarı bir çekişten sonra, kavrama bırakılsa bile tırmanmayı bitirir.\nİptal etmek için çubuğu oynat veya tutan eli yukarı it.",
  ["Ladder finish distance"] = "Merdiven bitiş mesafesi",
  ["Turning (right stick)"] = "Dönüş (sağ çubuk)",
  ["Snap turn"] = "Adımlı dönüş",
  ["Convert the right-stick X axis into discrete snap pulses\ninstead of smooth rotation. Helps with motion sickness."] = "Sağ çubuğun X eksenini yumuşak dönüş yerine\nayrık adımlı dönüşlere çevirir. Hareket hastalığına karşı yardımcı olur.",
  ["Snap angle"] = "Adım açısı",
  ["STEREO"] = "STEREO",
  ["PERFORMANCE"] = "PERFORMANS",
  ["NVIDIA Reflex"] = "NVIDIA Reflex",
  ["Game setting"] = "Oyun ayarı",
  ["Off (higher FPS)"] = "Kapalı (daha yüksek FPS)",
  ["On (lower latency)"] = "Açık (daha düşük gecikme)",
  ["On + Boost"] = "Açık + Boost",
  ["Off can improve GPU utilization and FPS, but may increase input latency."] = "Kapalı, GPU kullanımını ve FPS'i artırabilir ancak giriş gecikmesini yükseltebilir.",
  ["On"] = "Açık",
  ["Waiting for renderer"] = "Render motoru bekleniyor",
  ["Applied: %s"] = "Uygulandı: %s",
  ["STEREO VIEW"] = "STEREO GÖRÜNÜM",
  ["Mono mode"] = "Mono modu",
  ["One picture for both eyes, drawn once from the centre of the head:\nno depth, the most frames. Engine stereo and the second view are off."] = "Her iki göz için tek görüntü, başın merkezinden bir kez çizilir:\nderinlik yok, en yüksek kare hızı. Motor stereosu ve ikinci görünüm kapalı.",
  ["Restart the game to apply"] = "Uygulamak için oyunu yeniden başlatın",
  ["Motion prediction (ms)"] = "Hareket tahmini (ms)",
  ["%.1f ms"] = "%.1f ms",
  ["Forward-predicts the head pose by this many ms using head\nvelocity, hiding render-to-photon latency. 0 = off.\nTune up until motion feels responsive without overshoot."] = "Baş hızını kullanarak baş pozunu bu kadar ms ileri tahmin eder,\nrender ile foton arasındaki gecikmeyi gizler. 0 = kapalı.\nHareket aşmadan duyarlı hissedilene kadar artır.",
  ["Stereo separation x"] = "Stereo ayrımı x",
  ["Personal fine-tune on the auto IPD. 1.0 = calibrated natural\nseparation, auto-scaled to the headset's runtime IPD. Nudge\n0.8-1.2 for taste; crank to 3-5x to exaggerate depth and make\nthe eye alternation obvious on the flat monitor for testing."] = "Otomatik IPD üzerinde kişisel ince ayar. 1.0 = kalibre edilmiş doğal\nayrım, kulaklığın çalışma zamanı IPD'sine otomatik ölçeklenir. Zevke göre\n0.8-1.2; derinliği abartmak ve düz monitörde test için göz\ndeğişimini belirgin kılmak için 3-5x'e çıkar.",
  ["World scale"] = "Dünya ölçeği",
  ["Scales eye separation AND head translation together.\nLower it (e.g. 0.8) to make the world look\nBIGGER / yourself smaller; raise to shrink the world. Use this if V\nand NPCs feel too large."] = "Göz ayrımını VE baş yer değiştirmesini birlikte ölçekler.\nDünyanın daha BÜYÜK / senin daha küçük görünmesi için\nazalt (ör. 0.8); dünyayı küçültmek için artır. V\nve NPC'ler çok büyük görünüyorsa bunu kullan.",
  ["IPD scale"] = "IPD ölçeği",
  ["Eye-separation multiplier on the runtime IPD. 1.0 = the neutral\nbaseline (+-0.033 m on a typical headset).\nAffects stereo depth (diorama vs giant), NOT the monocular size."] = "Çalışma zamanı IPD'si üzerinde göz ayrımı çarpanı. 1.0 = nötr\ntaban (tipik bir kulaklıkta +-0.033 m).\nStereo derinliği etkiler (diorama veya dev), tek gözlü boyutu DEĞİL.",
  ["Reuse last clean frame"] = "Son temiz kareyi yeniden kullan",
  ["On stale ticks, re-submit the last clean captured eye and let\nthe compositor reproject it, instead of warping stale content\nagain. May lower submit rate\ntoward the capture rate. Off = always warp the stale eye."] = "Bayat tiklerde, bayat içeriği yeniden bükmek yerine son temiz yakalanan\ngözü yeniden gönderir ve kompozitörün yeniden yansıtmasına izin verir.\nGönderim hızını yakalama hızına doğru\ndüşürebilir. Kapalı = bayat gözü her zaman büker.",
  ["Asymmetric projection"] = "Asimetrik projeksiyon",
  ["ON: each eye renders exactly its own off-centre lens window\n(more of the panel used, square pixels).\nOFF: the symmetric frustum sized to the widest half-angle."] = "AÇIK: her göz tam olarak kendi merkez dışı mercek penceresini render eder\n(panelin daha fazlası kullanılır, kare pikseller).\nKAPALI: en geniş yarım açıya göre boyutlanan simetrik frustum.",
  ["AVATAR"] = "AVATAR",
  ["VR shortcuts and default game actions. Button names follow the Touch / Xbox convention; game actions use your controller bindings."] = "VR kısayolları ve varsayılan oyun eylemleri. Düğme adları Touch / Xbox kuralını izler; oyun eylemleri kontrolcü atamalarını kullanır.",
